### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> p(n), t(n);
    for (int i = 0; i < n; ++i) cin >> p[i];
    for (int i = 0; i < n; ++i) cin >> t[i];

    // 按类别分组
    vector<vector<int>> groups(3);
    for (int i = 0; i < n; ++i) {
        groups[t[i]].push_back(p[i]);
    }

    long long ans = 0;
    long long x = 1;  // 当前分配的处理编号
    for (int i = 0; i < 3; ++i) {
        sort(groups[i].begin(), groups[i].end());
        for (int val : groups[i]) {
            ans += abs(val - x);
            ++x;
        }
    }
    cout << ans << "\n";
    return 0;
}
